it.each([false, true])('holds Main reply bytes before native effect, expiry=%s', async expire => {
  const profile = { ...await fixture(retainedNativeInputPressureHostSource(serverUrl), 'raw'),
    requestTimeoutMs:3000 };
  let effects = 0, controls = 0, binding: HostCustodyBinding | undefined;
  const owner: HostCustodyOwner = { mainEpoch:'TEST-main-input', attach(context) {
    binding = context.binding;
    return { onReadable:()=>()=>{}, handle(call) {
      if (call.operation === 'write') { effects++; return {operation:'write',state:'completed'}; }
      if (call.operation === 'observe') { controls++; return {operation:'observe',root:'running'}; }
      throw new Error('TEST unexpected native effect');
    } };
  } };
  const transport = client(profile, owner); await transport.start();
  const gate = retainedNativeInputCompletionGate(transport);
  try {
    const requested = transport.request('TEST.blocked-native', {expire,payload:'x'.repeat(1024*1024-2048)});
    await Promise.race([gate.blocked, requested.then(()=>{ throw new Error('TEST missing original write barrier'); })]);
    await Promise.race([gate.queued, requested.then(()=>{ throw new Error('TEST native call never reached Main admission'); })]);
    if (expire) expect(await requested).toMatchObject({status:expect.stringMatching(/^(unknown|refused)$/u)});
    expect(effects).toBe(0);
    expect(await transport.request('TEST.control', undefined, {control:true}))
      .toMatchObject({status:'completed',value:{operation:'observe'}});
    expect(controls).toBe(1); expect(effects).toBe(0);
    gate.release();
    if (!expire) expect(await requested).toEqual({status:'completed',value:{operation:'write',state:'completed'}});
    expect(effects).toBe(expire?0:1);
    if (!expire) {
      if (!binding) throw new Error('TEST original binding missing');
      await expect(transport.request('TEST.missing-budget', {binding}, {control:true}))
        .rejects.toMatchObject({code:'protocol-error',outcome:'unknown'});
      expect(effects, 'An incompatible private envelope cannot start another effect').toBe(1);
    }
  } finally { gate.restore(); await transport.shutdown(); }
});

/** Hold only the original Main callback, after its real child stdin write completes. */
export function retainedNativeInputCompletionGate(client: object) {
  const captured: unknown = Object.getOwnPropertyDescriptor(client, 'child')?.value;
  if (!(captured instanceof ChildProcess) || !captured.stdin) throw new Error('TEST original Host missing');
  const pending: unknown = Object.getOwnPropertyDescriptor(client, 'nativePending')?.value;
  if (!(pending instanceof Map)) throw new Error('TEST original reverse request map missing');
  const entries: Map<unknown, unknown> = pending, originalSet = entries.set;
  let admitted!: () => void;
  const queued = new Promise<void>(resolve => { admitted = resolve; });
  const trackedSet: typeof entries.set = (key, value) => {
    const result = originalSet.call(entries, key, value); admitted(); return result;
  };
  entries.set = trackedSet;
  const stream = captured.stdin, original = stream.write, write = original.bind(stream);
  let releaseCallback: (() => void) | undefined, released = false, intercepted = false;
  let complete!: () => void, fail!: (error: Error) => void;
  const blocked = new Promise<void>((resolve, reject) => { complete = resolve; fail = reject; });
  const gate = (chunk: unknown, encodingOrCallback?: BufferEncoding | ((error?: Error | null) => void),
    callback?: (error?: Error | null) => void): boolean => {
    const done = typeof encodingOrCallback === 'function' ? encodingOrCallback : callback;
    const encoding = typeof encodingOrCallback === 'string' ? encodingOrCallback : undefined;
    let target = false;
    if (Buffer.isBuffer(chunk) && !intercepted) {
      const value: unknown = JSON.parse(chunk.toString('utf8'));
      target = typeof value === 'object' && value !== null && 'method' in value &&
        value.method === 'TEST.blocked-native';
    }
    if (!target) return encoding ? write(chunk, encoding, done) : write(chunk, done);
    if (!done) throw new Error('TEST original Main write callback missing');
    intercepted = true;
    const observed = (error?: Error | null) => {
      if (error) { done(error); fail(error); return; }
      releaseCallback = () => done();
      complete();
      if (released) { const release = releaseCallback; releaseCallback = undefined; release(); }
    };
    return encoding ? write(chunk, encoding, observed) : write(chunk, observed);
  };
  stream.write = gate;
  const release = () => {
    released = true;
    const callback = releaseCallback; releaseCallback = undefined; callback?.();
  };
  return {
    blocked, queued, release,
    restore() {
      release();
      if (stream.write === gate) stream.write = original;
      if (entries.set === trackedSet) entries.set = originalSet;
    },
  };
}

export function retainedNativeInputPressureHostSource(serverUrl: string): string {
  return `
    import { createHostServer } from ${JSON.stringify(serverUrl)};
    const server=createHostServer({input:process.stdin,output:process.stdout,buildId:'TEST-host-v1',
      nativeCustody:{timeoutMs:2000},methods:{
        'TEST.blocked-native':{lane:'work',handle:params=>server.nativeCustody.request(
          {operation:'write',capability:'TEST-original',bytes:'YQ=='},
          params.expire?performance.now()+20:undefined)},
        'TEST.control':{lane:'control',handle:()=>server.nativeCustody.request(
          {operation:'observe',capability:'TEST-original'})},
        'TEST.missing-budget':{lane:'control',handle:params=>{
          process.stdout.write(JSON.stringify({jsonrpc:'2.0',
            id:'custody:'+server.handshake.hostIncarnation+':work:99',method:'host.native-custody',
            params:{binding:params.binding,call:{operation:'write',capability:'TEST-original',bytes:'Yg=='}}})+'\\n');
          return 'sent';
        }}
      }});
    void server.closed.then(()=>process.exit(0));
  `;
}

request(value: HostCustodyCall, deadlineMs?: number): Promise<HostCustodyReply> {
  const parsed = callSchema.safeParse(value);
  return parsed.success
    ? this.requestWhenReady(parsed.data.operation, () => parsed.data, deadlineMs)
    : Promise.resolve({ status: 'refused' });
}

/** Only references wait here. The builder receives the fixed deadline after queueing and timeout clamping. */
requestWhenReady(
  operation: HostCustodyCall['operation'],
  build: (deadlineMs: number) => HostCustodyCall,
  deadlineMs?: number
): Promise<HostCustodyReply> {
  const now = performance.now();
  const deadline = Math.min(deadlineMs ?? now + this.options.timeoutMs, now + this.options.timeoutMs);
  const queued = this.admissions.control.length + this.admissions.work.length;
  if (this.sealed || !this.binding || this.next > MAX_SEQUENCE ||
    (this.inputSealed && !hostCustodyCleanup({ operation })) ||
    !Number.isFinite(deadline) || deadline <= now || queued + this.pending.size >= 6 * 256)
    return Promise.resolve({ status: 'refused' });
  const lane = hostCustodyControl({ operation }) ? this.admissions.control : this.admissions.work;
  return new Promise((resolve) => {
    let settled = false;
    const admission: NativeAdmission = {
      operation, build, deadline,
      timer: setTimeout(() => admission.finish({ status: 'refused' }), deadline - now),
      finish: (reply) => {
        if (settled) return;
        settled = true;
        clearTimeout(admission.timer);
        const index = lane.indexOf(admission);
        if (index >= 0) lane.splice(index, 1);
        resolve(reply);
        this.resumeAdmission();
      },
    };
    lane.push(admission);
    this.resumeAdmission();
  });
}

/** Called when the original output write frees shared bytes, or a reply frees a request slot. */
resumeAdmission(): void {
  if (this.admitting || this.sealed) return;
  this.admitting = true;
  try {
    for (;;) {
      const lane = this.admissions.control.length ? this.admissions.control : this.admissions.work;
      const admission = lane[0];
      if (!admission) return;
      const control = hostCustodyControl(admission);
      const capacity = this.options.limits.maxPendingRequests -
        (control ? 0 : this.options.limits.reservedControlRequests);
      if (admission.deadline <= performance.now() ||
        (this.inputSealed && !hostCustodyCleanup(admission))) {
        admission.finish({ status: 'refused' });
        continue;
      }
      if (this.pending.size >= capacity || this.options.canSend?.(control) === false) return;
      lane.shift();
      clearTimeout(admission.timer);
      let parsed: ReturnType<typeof callSchema.safeParse>;
      try { parsed = callSchema.safeParse(admission.build(admission.deadline)); }
      catch { admission.finish({ status: 'refused' }); continue; }
      if (!parsed.success || parsed.data.operation !== admission.operation) {
        admission.finish({ status: 'refused' }); continue;
      }
      // dispatch rechecks the original deadline after the lazy builder, without extending it.
      void this.dispatch(parsed.data, admission.deadline).then(admission.finish);
    }
  } finally { this.admitting = false; }
}

private dispatch(call: HostCustodyCall, deadline: number): Promise<HostCustodyReply> {
  if (this.sealed || !this.binding || this.next > MAX_SEQUENCE ||
    (this.inputSealed && !hostCustodyCleanup(call)))
    return Promise.resolve({ status: 'refused' });
  const remaining = Math.floor(deadline - performance.now());
  if (!Number.isFinite(remaining) || remaining <= 0) return Promise.resolve({ status: 'refused' });
  const control = hostCustodyControl(call);
  if (call.operation === 'read' && [...this.pending.values()].some(({ call: other }) =>
    other.operation === 'read' && other.capability === call.capability && other.stream === call.stream))
    return Promise.resolve({ status: 'refused' });
  const id = `custody:${this.binding.hostIncarnation}:${control ? 'control' : 'work'}:${this.next++}`;
  const hintKey = hostCustodyHintKey(call);
  const admittedHint = hintKey ? this.hints.get(hintKey) : undefined;
  const wireCall = call.operation === 'allocate' ? (() => {
    const { runtimeSourceOrigin, ...original } = call;
    return runtimeSourceOrigin === undefined ? original : { ...original, runtimeSourceOrigin };
  })() : call;
  const frame: RpcRequest = {
    jsonrpc: '2.0', id, method: HOST_CUSTODY_METHOD, params: { binding: this.binding, call: wireCall, remainingMs: remaining },
  };
  return new Promise((resolve) => {
    let returned = false;
    const settle = (reply: HostCustodyReply) => {
      if (!returned) { returned = true; resolve(reply); }
    };
    const finish = (reply: HostCustodyReply) => {
      const pending = this.pending.get(id);
      if (!pending) return;
      clearTimeout(pending.timer);
      this.pending.delete(id);
      if (reply.status === 'completed' && hintKey) {
        const current = this.hints.get(hintKey);
        if (current === admittedHint) this.hints.delete(hintKey);
        else if (current) for (const observer of this.observers) observer(current);
      }
      if (reply.status === 'completed' && reply.value.operation === 'release' && reply.value.state === 'released')
        for (const key of this.hints.keys()) if (key.startsWith(`${call.capability}:`)) this.hints.delete(key);
      settle(reply);
      this.resumeAdmission();
    };
    // A caller timeout is not an ACK: retain its slot, ID and marker until the original reply.
    const expire = () => settle({ status: 'unknown' });
    const timer = setTimeout(expire, remaining);
    this.pending.set(id, { call, finish, timer });
    try { if (!this.options.send(frame, control)) finish({ status: 'refused' }); }
    catch { expire(); }
  });
}

